// Map extracted leads to Supabase `leads` rows with provenance.
const body = $('Webhook').item.json.body || {};
const extracted = JSON.parse($('Claude: Extract Leads').item.json.message.content);
const leads = (extracted.leads || []).map(l => ({
  full_name: l.full_name || null,
  email: l.email || null,
  linkedin_url: l.linkedin_url || null,
  twitter_handle: l.twitter_handle || null,
  company: l.company || null,
  title: l.title || null,
  source_type: body.drive_file_id ? 'drive_import' : 'drive_import',
  source_ref: body.drive_file_id || null,
  source_url: body.source_url || null,
  source_document_id: body.drive_file_id || null,
  source_document_name: body.source_document_name || null,
  fit_score: l.fit_score || null,
  tier: l.tier || null,
  why_relevant: l.why_relevant || null,
  primary_tension: l.primary_tension || null,
  status: 'new',
  raw_extraction: l,
}));
return leads.map(l => ({ json: l }));
